-- GenDB engine variant Q20-wrapped_tables: template q20.sql, kind wrapped_tables (generated by generate.py; frozen)
SELECT
  s_name,
  s_address
FROM (
  SELECT
    *
  FROM supplier
) AS supplier, (
  SELECT
    *
  FROM nation
) AS nation
WHERE
  s_suppkey IN (
    SELECT
      ps_suppkey
    FROM (
      SELECT
        *
      FROM partsupp
    ) AS partsupp
    WHERE
      ps_partkey IN (
        SELECT
          p_partkey
        FROM (
          SELECT
            *
          FROM part
        ) AS part
        WHERE
          p_name LIKE $1
      )
      AND ps_availqty > (
        SELECT
          0.5 * SUM(l_quantity)
        FROM (
          SELECT
            *
          FROM lineitem
        ) AS lineitem
        WHERE
          l_partkey = ps_partkey
          AND l_suppkey = ps_suppkey
          AND l_shipdate >= $2
          AND l_shipdate < $2 + INTERVAL '1 YEAR'
      )
  )
  AND s_nationkey = n_nationkey
  AND n_name = $3
ORDER BY
  s_name
